        // ===== CANLI VELİ İZLEME — admin, sporcuya özel PIN'siz izleme linki üretir/paylaşır =====
        async function canliIzlemeLinkiGoster(g, ad) {
            try {
                let res = await fetch(`/api/athletes/${encodeURIComponent(g)}/${encodeURIComponent(ad)}/izle-kodu`, { method: 'POST' });
                let data = await res.json().catch(() => ({}));
                if(!res.ok || !data.kod) { showToast('Link oluşturulamadı.', 'error'); return; }
                let link = location.origin + '/izle.html?kod=' + data.kod;
                document.getElementById('izle-linki-baslik').textContent = '🔗 ' + ad + ' — Canlı İzleme Linki';
                document.getElementById('izle-linki-input').value = link;
                document.getElementById('izle-linki-qr').src = 'https://api.qrserver.com/v1/create-qr-code/?size=180x180&data=' + encodeURIComponent(link);
                document.getElementById('izle-linki-modal').style.display = 'flex';
            } catch(e) { showToast('Link oluşturulamadı (bağlantı hatası).', 'error'); }
        }
        // ===== SPORCU FOTOĞRAFI — SADECE yönetici/eğitmen yükler (PIN'siz sporcu girişinden ASLA
        // erişilemez, moderasyon/KVKK riskini önlemek için bilinçli tercih). `profilKapakYukle`
        // (self-servis "kapak" fotoğrafı) ile AYNI canvas-küçültme deseni, ama daha küçük hedef boyut
        // (avatar — kapak fotoğrafı değil) ve ayrı, admin-only `fotoUrl` alanına yazıyor.
        function sporcuFotoYukle(g, ad, ev) {
            let dosya = ev.target.files && ev.target.files[0]; if(!dosya) return;
            let reader = new FileReader();
            reader.onload = function(e) {
                let img = new Image();
                img.onload = async function() {
                    let c = document.createElement('canvas'); let mw = 300; let oran = Math.min(1, mw / img.width);
                    c.width = img.width * oran; c.height = img.height * oran;
                    c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
                    let dataUrl = c.toDataURL('image/jpeg', 0.8);
                    try {
                        let res = await fetch(`/api/athletes/${encodeURIComponent(g)}/${encodeURIComponent(ad)}`, {
                            method: 'PATCH', headers: {'content-type':'application/json'},
                            body: JSON.stringify({ fields: { fotoUrl: dataUrl }, lastModified: Date.now() })
                        });
                        let data = await res.json().catch(() => ({}));
                        if(!res.ok || !data.applied) { showToast('Fotoğraf yüklenemedi, tekrar dene.', 'error'); return; }
                        if(turnuvaDB[g] && turnuvaDB[g][ad]) { turnuvaDB[g][ad].fotoUrl = dataUrl; localStorage.setItem('okculuk_premium_data', JSON.stringify(turnuvaDB)); }
                        showToast('📷 Fotoğraf güncellendi!', 'success');
                        try { yoneticiPaneliCiz(); } catch(e) {}
                    } catch(e) { showToast('Fotoğraf yüklenemedi (bağlantı hatası).', 'error'); }
                };
                img.src = e.target.result;
            };
            reader.readAsDataURL(dosya);
            ev.target.value = '';
        }
        function izleLinkiKopyala() {
            let input = document.getElementById('izle-linki-input'); if(!input) return;
            input.select();
            let bitti = () => showToast('📋 Kopyalandı!', 'success');
            if(navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(input.value).then(bitti).catch(() => { document.execCommand('copy'); bitti(); });
            else { try { document.execCommand('copy'); } catch(e) {} bitti(); }
        }
        function yoneticiDusukHazirOlmaListesi() {
            let bugun = bugunISO(); let liste = [];
            ['buyukler','yildizlar','kucukler','minikler'].forEach(g => {
                Object.keys(turnuvaDB[g] || {}).forEach(ad => {
                    let sp = turnuvaDB[g][ad]; if(sp.pasif || sp.donduruldu) return;
                    let h = sp.hazirOlma;
                    if(h && h.tarih === bugun) { let skor = hazirOlmaSkoru(h); if(skor < 5 || h.sakatlik) liste.push({ g, ad, skor, sakatlik: !!h.sakatlik, sakatlikNotu: h.sakatlikNotu || '' }); }
                });
            });
            return liste;
        }
        // Yoklama birleştirme (cihazlar arası kayıp olmasın — birleşim, en erken saat)
        function otomatikYoklamaMerge(yerel, uzak) {
            let sonuc = {}; let gunler = new Set([...Object.keys(yerel||{}), ...Object.keys(uzak||{})]);
            gunler.forEach(gun => {
                sonuc[gun] = {}; let a = (yerel && yerel[gun]) || {}, b = (uzak && uzak[gun]) || {};
                let adlar = new Set([...Object.keys(a), ...Object.keys(b)]);
                adlar.forEach(ad => { let x = a[ad], y = b[ad]; if(x && !y) sonuc[gun][ad] = x; else if(y && !x) sonuc[gun][ad] = y; else if(x.elle && !y.elle) sonuc[gun][ad] = x; else if(y.elle && !x.elle) sonuc[gun][ad] = y; else { sonuc[gun][ad] = ((x.saat||'99') <= (y.saat||'99')) ? x : y; } });
            });
            return sonuc;
        }
        let skorSinifFiltre = '__hepsi'; let skorAramaFiltre = '';
