                    (kopya.seriler||[]).forEach(sr => { if(sr.seriId && !ids[sr.seriId]) { hedef.seriler = hedef.seriler || []; hedef.seriler.push(sr); ids[sr.seriId] = 1; } });
                    // Elmasları kaybetme — coinT'si daha yeni olan kazanır
                    if((kopya.coinT||0) > (hedef.coinT||0)) ['coin','coinT','oyun','magaza','ozelRozetler','gorev','monopoly','kisiselHedef'].forEach(f => { if(kopya[f] !== undefined) hedef[f] = kopya[f]; });
                    hedef.lastModified = Math.max(hedef.lastModified||0, kopya.lastModified||0);
