        function bulutaYukleManuel() {
            if(!bulutHazir) { showToast('Bulut bağlı değil.', 'warning'); return; }
            if(sporcuSayisi(turnuvaDB) === 0 && jsonSporcuSayisi(sonBulutJSON) > 0) {
                if(!confirm('DİKKAT: Şu an cihazda hiç sporcu yok ama bulutta var.\nBuluta yüklersen buluttaki tüm sporcular SİLİNİR.\nEmin misin?')) return;
            }
            let json = bulutVeriJSON(); sonBulutJSON = json;
            bulutDurum('☁️ yükleniyor...', 'var(--gold)');
            dbBulut.collection('kulup').doc('master').set({ veri: json, guncelleme: Date.now() })
                .then(() => { guvenlikYedegiAl(); showToast('Buluta yüklendi ☁️⬆️', 'success'); bulutDurum('☁️ kaydedildi', 'var(--neon-green)'); })
                .catch(() => { showToast('Yükleme hatası.', 'error'); bulutDurum('☁️ hata', 'var(--neon-red)'); });
        }
        function acilKurtarma() {
            let j = localStorage.getItem('okculuk_yedek_son');
            let z = localStorage.getItem('okculuk_yedek_son_zaman') || 'bilinmiyor';
            if(!j) { showToast('Otomatik yedek bulunamadı.', 'warning'); return; }
            let say = jsonSporcuSayisi(j);
            if(say === 0) { showToast('Yedekte sporcu yok.', 'warning'); return; }
            if(!confirm(`Son otomatik yedeği geri yükle?\n\n📅 Yedek zamanı: ${z}\n👥 ${say} sporcu\n\nMevcut veriler bununla değiştirilecek.`)) return;
            try {
                bulutVeriyiUygula(JSON.parse(j));
                showToast(`Kurtarıldı! ${say} sporcu geri geldi 🛟`, 'success');
                if(bulutHazir) bulutaYukleManuel(); // kurtarılan veriyi buluta da yaz
            } catch(e) { showToast('Kurtarma hatası.', 'error'); }
        }
        function bulutManuelYenile() {
            if(!bulutHazir) { showToast('Bulut bağlı değil.', 'warning'); return; }
            bulutDurum('☁️ yenileniyor...', 'var(--gold)');
            // Önce master'dan çek (sporcu profilleri, temel bilgiler)
            dbBulut.collection('kulup').doc('master').get().then(doc => {
                if(doc.exists && doc.data() && doc.data().veri) {
                    bulutVeriyiUygula(JSON.parse(doc.data().veri));
                    sonBulutJSON = doc.data().veri;
                }
                // Sonra seri bazlı kayıtları çek (en güncel skorlar)
                return dbBulut.collection('kulup').doc('seriler').collection('kayitlar').get();
            }).then(snap => {
                if(!snap) { showToast('Buluttan yenilendi ☁️', 'success'); bulutDurum('☁️ senkron', 'var(--neon-green)'); return; }
                let degisti = false;
                snap.forEach(d => {
                    let s = d.data(); if(!s || !s.g || !s.ad || !s.oklar) return;
                    if(silindiMi(s.g, s.ad)) return;
                    if(!turnuvaDB[s.g]) turnuvaDB[s.g] = {};
                    if(!turnuvaDB[s.g][s.ad]) return;
                    let sp = turnuvaDB[s.g][s.ad];
                    if(!sp.seriler) sp.seriler = [];
                    if(!sp.seriler.some(sr => sr.seriId === s.id)) {
                        sp.seriler.push({ seriId: s.id, puan: s.puan, oklar: s.oklar, tarih: s.tarih, t: s.t });
                        sp.toplamSkor = sp.seriler.reduce((a,sr)=>a+(sr.puan||0),0);
                        sp.xAdet = sp.seriler.reduce((a,sr)=>a+((sr.oklar||[]).filter(o=>o==='X').length),0);
                        sp.sonSkorZamani = Math.max(sp.sonSkorZamani||0, s.t||0) || sp.sonSkorZamani;
                        degisti = true;
                    }
                });
                if(degisti) localStorage.setItem('okculuk_premium_data', JSON.stringify(turnuvaDB));
                showToast('Buluttan yenilendi ☁️✅', 'success');
                bulutDurum('☁️ senkron', 'var(--neon-green)');
                try { siralamaListesiDoldur(); klasmanDoldur(); } catch(e) {}
            }).catch(() => showToast('Bulut hatası.', 'error'));
        }

