            if(!sp) { for(let g in turnuvaDB) { if(turnuvaDB[g] && turnuvaDB[g][ad]) { sp = turnuvaDB[g][ad]; break; } } }
            if(!sp) return;
            let kod = String(sp.kod || sp.dogumYili || '').trim();
            let url = location.origin + location.pathname + '?vs=' + encodeURIComponent(ad) + (kod ? '&vk=' + encodeURIComponent(kod) : '');
