        var KM_OYUN_ARENA_KARAKTERLER_KADIN = ['okcu-elf-kadin', 'okcu-sari-sacli'];
        var KM_OYUN_ARENA_KARAKTERLER_ERKEK = ['okcu-kirmizi-genc', 'okcu-orman-elfi', 'okcu-pelerinli'];
