                    + '<div style="text-align:center; font-size:9.5px; font-weight:800; color:' + (parca > 0 ? 'var(--accent-orange)' : 'var(--text-muted)') + '; margin-bottom:7px;">' + parca + '/' + m.parca + ' parça' + (parca > 0 ? ' — ' + (m.parca - parca) + ' kaldı! 🔥' : '') + '</div>'
